/**
 * Foody Vrinda - Human Identity & Name Utilities
 * 
 * Accurately detects autogenerated placeholder identities (e.g. "Customer", "Guest",
 * "Customer (1234)", "Member (1234)", "User (abc123)") and validates authentic human names
 * supporting Unicode letters across all Indian and international scripts (Devanagari/Hindi, etc.).
 */

/**
 * Checks whether a given string is a system-generated placeholder name
 * @param {string} name
 * @returns {boolean}
 */
export function isAutoGeneratedName(name) {
  if (!name || typeof name !== 'string') return true;
  const s = name.trim();
  if (!s) return true;
  if (/^Sarathi(\s+Gopal)?$/i.test(s)) return true;
  if (/^(Guest|Customer|Devotee|User|Member)(\s+User)?$/i.test(s)) return true;
  if (/^(Guest|Customer|Devotee|User|Member|Sarathi)\s*([(#]\s*[\w\d-]+\s*\)?|\d+)$/i.test(s)) return true;
  if (/^(Guest|Customer|Devotee|User|Member)\s+([a-z0-9_-]+)$/i.test(s)) return true;
  return false;
}

/**
 * Validates whether a name contains authentic human characters
 * Supports English letters, Devanagari/Hindi (\p{L} and \p{M}), spaces, apostrophes, dots, and hyphens.
 * Length must be between 2 and 60 characters.
 * @param {string} name
 * @returns {boolean}
 */
export function isValidHumanName(name) {
  if (!name || typeof name !== 'string') return false;
  const s = name.trim();
  if (s.length < 2 || s.length > 60) return false;
  // Rejects known system placeholders
  if (isAutoGeneratedName(s)) return false;
  // Allows Unicode letters and vowel marks across Devanagari, English, and other scripts
  const nameRegex = /^[\p{L}\p{M}\s'.-]{2,60}$/u;
  return nameRegex.test(s);
}
